pair<int, int> rot(int dir)
{
  if(dir == UP)
    return make_pair(UPLEFT , UPRIGHT);
  if(dir == DOWN)
    return make_pair(DOWNLEFT , DOWNRIGHT);
  if(dir == LEFT)
    return make_pair(UPLEFT, DOWNLEFT);
  if(dir == RIGHT)
    return make_pair(UPRIGHT , DOWNRIGHT);
